#pragma once

// The compiled form of mesh.metal, checked in beside it.
//
// Embedded rather than built, so the tier-2 binary needs neither the shader library nor the Metal toolchain —
// the same reason double_compute.metallib.h is embedded.
// The command line that produced it is in mesh.metal's own comment, so it is reproducible by hand.
//
// One library, nine entry points: the vertex and fragment stages of an indexed draw that reads its colour from a
// vertex attribute and its tint from inline constants, four kernels — one taking inline constants, one taking an
// array binding, one writing the vertex buffer a draw then reads, and one copying a readonly buffer into a
// readwrite one — and the three stages of the fragment-write hazard, where one draw writes what the next reads.

#include <clean-core/fwd.hh>

